// ── VALIDATE & NORMALIZE ──────────────────────────────────────────────────
// Accepts two payload shapes:
//
//  Path A — Pre-built xlsx (Claude Code generated a real binary):
//    { sessionId, itemId, studyUnitId, fileName, file_base64 }
//
//  Path B — MCQ JSON array (n8n builds CSV natively — no xlsx package needed):
//    { sessionId, itemId, studyUnitId, mcqs: [...] }
//
// itemId always comes from the Claude agent session — no lookup needed.

const body = $json.body ?? $json;

// itemId and studyUnitId are always required
const baseRequired = ['itemId', 'studyUnitId'];
const missing = baseRequired.filter(f => !body[f]);

if (missing.length > 0) {
  throw new Error(JSON.stringify({
    error: 'Missing required fields',
    missing,
    received: Object.keys(body)
  }));
}

const today = new Date().toISOString().slice(0, 10);
const fileName = body.fileName ?? `${body.studyUnitId}_mcqs_${today}.xlsx`;

// PATH A: pre-built base64 xlsx sent directly by Claude Code
if (body.file_base64) {
  return [{
    json: {
      path:        'A',
      itemId:      String(body.itemId),
      studyUnitId: body.studyUnitId,
      sessionId:   body.sessionId ?? '',
      fileName,
      mimeType:    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      xlsxBase64:  body.file_base64,
      rowCount:    null  // unknown without parsing
    }
  }];
}

// PATH B: MCQ JSON array — validate and normalize
if (!body.mcqs || !Array.isArray(body.mcqs) || body.mcqs.length === 0) {
  throw new Error(JSON.stringify({
    error: 'Payload must include either file_base64 (Path A) or a non-empty mcqs array (Path B)',
    received: Object.keys(body)
  }));
}

// Normalize to WATU Pro 11-column format
const mcqRows = body.mcqs.map((q, i) => ({
  '#':              i + 1,
  'Question':       q.question_text  ?? q.question  ?? '',
  'Choice A':       q.choice_a       ?? q.option_a  ?? '',
  'Choice B':       q.choice_b       ?? q.option_b  ?? '',
  'Choice C':       q.choice_c       ?? q.option_c  ?? '',
  'Choice D':       q.choice_d       ?? q.option_d  ?? '',
  'Correct Answer': q.correct_answer ?? 'A',
  'Explanation':    q.explanation    ?? '',
  'Bloom Level':    q.bloom_level    ?? '',
  'Topic':          q.topic          ?? '',
  'Study Unit':     q.study_unit     ?? body.studyUnitId ?? ''
}));

return [{
  json: {
    path:        'B',
    itemId:      String(body.itemId),
    studyUnitId: body.studyUnitId,
    sessionId:   body.sessionId ?? '',
    fileName,
    rowCount:    mcqRows.length,
    mcqRows
  }
}];

// ── BUILD CSV (Path B only) ────────────────────────────────────────────────
// Generates a CSV file using only built-in JavaScript — no npm packages needed.
// Works on n8n Cloud and self-hosted without any community nodes.
//
// Columns match WATU Pro 11-column MCQ format.

const { itemId, studyUnitId, sessionId, fileName, rowCount, mcqRows } = $json;

const headers = [
  '#', 'Question', 'Choice A', 'Choice B', 'Choice C', 'Choice D',
  'Correct Answer', 'Explanation', 'Bloom Level', 'Topic', 'Study Unit'
];

// RFC 4180 CSV escaping
const csvEscape = (val) => {
  const str = String(val ?? '');
  if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
};

const csvLines = [
  headers.map(csvEscape).join(','),
  ...mcqRows.map(row => headers.map(h => csvEscape(row[h])).join(','))
];

const csvString = csvLines.join('\r\n');
const csvBase64 = Buffer.from(csvString, 'utf8').toString('base64');

// Use .csv extension
const csvFileName = fileName.replace(/\.xlsx$/i, '.csv');

return [{
  json: {
    itemId,
    studyUnitId,
    sessionId,
    fileName:   csvFileName,
    mimeType:   'text/csv',
    rowCount,
    xlsxBase64: csvBase64
  }
}];

// ── UPLOAD FILE TO MONDAY.COM ─────────────────────────────────────────────
// Runs for both Path A (xlsx) and Path B (csv) — both arrive with xlsxBase64.
//
// Monday requires multipart/form-data POST to /v2/file (NOT /v2).
// Standard JSON GraphQL calls do not support file uploads.
//
// Board:  HOCK International Content Production (18398486903)
// Column: MCQs File (file_mm0vtzzb)

const credentials = await this.getCredentials('mondayComApi');
const token = credentials.apiToken;

const { itemId, fileName, xlsxBase64, mimeType, studyUnitId, sessionId, rowCount } = $json;

const fileBuffer = Buffer.from(xlsxBase64, 'base64');

// Detect content type: use explicit mimeType if provided, else infer from fileName
const contentType = mimeType ??
  (fileName.endsWith('.csv')
    ? 'text/csv'
    : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');

const COLUMN_ID = 'file_mm0vtzzb';

const mutation = `mutation ($file: File!) {
  add_file_to_column(
    item_id: ${itemId},
    column_id: "${COLUMN_ID}",
    file: $file
  ) { id }
}`;

// Monday GraphQL multipart spec:
//   Part "query" → the mutation string
//   Part "map"   → maps part name "0" to variables.file
//   Part "0"     → the actual file binary
const boundary = `----MCQUpload${Date.now()}`;
const CRLF = '\r\n';

const queryPart =
  `--${boundary}${CRLF}` +
  `Content-Disposition: form-data; name="query"${CRLF}${CRLF}` +
  `${mutation}${CRLF}`;

const mapPart =
  `--${boundary}${CRLF}` +
  `Content-Disposition: form-data; name="map"${CRLF}${CRLF}` +
  `{"0": ["variables.file"]}${CRLF}`;

const fileHeader =
  `--${boundary}${CRLF}` +
  `Content-Disposition: form-data; name="0"; filename="${fileName}"${CRLF}` +
  `Content-Type: ${contentType}${CRLF}${CRLF}`;

const closing = `${CRLF}--${boundary}--`;

const fullBody = Buffer.concat([
  Buffer.from(queryPart + mapPart + fileHeader, 'utf8'),
  fileBuffer,
  Buffer.from(closing, 'utf8')
]);

const response = await this.helpers.httpRequest({
  method:  'POST',
  url:     'https://api.monday.com/v2/file',
  headers: {
    'Authorization': token,
    'Content-Type':  `multipart/form-data; boundary=${boundary}`,
    'API-Version':   '2024-01'
  },
  body:               fullBody,
  returnFullResponse: true
});

if (response.statusCode !== 200) {
  throw new Error(`Monday upload failed [${response.statusCode}]: ${JSON.stringify(response.body)}`);
}

const result = typeof response.body === 'string'
  ? JSON.parse(response.body)
  : response.body;

if (result.errors?.length) {
  throw new Error(`Monday GraphQL error: ${JSON.stringify(result.errors)}`);
}

return [{
  json: {
    itemId,
    studyUnitId,
    sessionId,
    fileName,
    rowCount:    rowCount ?? 'n/a',
    mondayFileId: result?.data?.add_file_to_column?.id ?? null
  }
}];

// Format error for clean webhook response
const errorData = $json.error ?? {};
const message = typeof errorData === 'string'
  ? errorData
  : (errorData.message ?? JSON.stringify(errorData));

let parsed = {};
try   { parsed = JSON.parse(message); }
catch { parsed = { error: message };  }

return [{
  json: {
    errorMessage: parsed.error    ?? message,
    missing:      parsed.missing  ?? [],
    received:     parsed.received ?? []
  }
}];
